/* ===================== CHỦ ĐỀ 4 và 5 · LỚP 1–5 ===================== */
/* L1: Hình khối, vị trí · Ôn tập HK1 | L2: Cộng trừ có nhớ phạm vi 100 · Hình phẳng | L3: Nhân chia phạm vi 100 · mm, g, ml, nhiệt độ
   L4: Yến tạ tấn, dm² m² mm², giây thế kỉ · Cộng trừ số nhiều chữ số | L5: Phép tính số thập phân · Hình phẳng, chu vi, diện tích.
   Đề viết mới theo kiến thức từng tiết trong Vở BT-TH (đổi đồ vật, bối cảnh, số liệu). */
const dz=(n,d)=>{let s=dv(n,d);if(s.includes(','))s=s.replace(/0+$/,'').replace(/,$/,'');return s};
const colPic=(a,op,b)=>`<div class="g1col"><span>${a}</span><span><em>${op}</em>${b}</span><i></i><span class="q">?</span></div>`;
const WQ=(q,say,a,sol)=>NQ(q,say,a,sol,'Toán lời văn');
/* ---------- LỚP 1 ---------- */
const SOL1=[['Con xúc xắc','lp'],['Khối ru-bích','lp'],['Hộp quà hình vuông','lp'],['Hộp sữa tươi','hh'],['Viên gạch','hh'],['Bao diêm','hh'],['Cái tủ lạnh','hh'],['Hộp bút','hh']];
const SOLN={lp:'Khối lập phương',hh:'Khối hộp chữ nhật'};
function cubeStack(hs){const S=26,W=hs.length*S+12,H=Math.max(...hs)*S+12;let o='';hs.forEach((h,i)=>{for(let j=0;j<h;j++){const x=6+i*S,y=H-6-(j+1)*S;o+=`<rect x="${x}" y="${y}" width="${S}" height="${S}" fill="#FCB40C" stroke="#1F2A5A" stroke-width="3"/><rect x="${x+3}" y="${y+3}" width="${S-6}" height="5" fill="#FDE08A"/>`}});return`<svg viewBox="0 0 ${W} ${H}" width="${W*1.6}" height="${H*1.6}" shape-rendering="crispEdges" aria-hidden="true">${o}</svg>`}
const QP1={
 solid:()=>()=>{const [o,k]=pick(SOL1);return CQ(`<b>${o}</b> có dạng khối gì?`,`${o} có dạng khối gì?`,SOLN[k],[SOLN[k==='lp'?'hh':'lp']],`${o} có dạng ${SOLN[k].toLowerCase()}.`,'Khối lập phương, khối hộp chữ nhật')},
 cubes:()=>()=>{const hs=Array.from({length:R(2,4)},()=>R(1,3)),n=hs.reduce((a,b)=>a+b,0);return OQ('Hình bên được xếp bởi mấy khối lập phương?','Hình bên được xếp bởi mấy khối lập phương nhỏ? Em đếm từng cột nhé.',n,1,12,`Đếm từng cột: ${hs.join(' + ')} = ${n}.`,'Đếm khối lập phương',`<div class="g1grp">${cubeStack(hs)}</div>`)},
 cube5:()=>()=>{const n=R(4,6),L=shuf([n,n,n+pick([-1,1]),R(3,7)]).slice(0,3);const opts=[...new Set(L)];while(opts.length<3){const v=R(3,8);if(!opts.includes(v))opts.push(v)}const ord=shuf(opts);const mk=v=>{const hs=[];let r=v;while(r>0){const h=Math.min(r,R(1,3));hs.push(h);r-=h}return cubeStack(hs)};return{type:'opt',cols:3,q:`Hình nào được xếp bởi <b>${n}</b> khối lập phương?`,say:`Hình nào được xếp bởi ${NUMW[n]} khối lập phương nhỏ?`,opts:ord.map(v=>({h:mk(v).replace(/width="[\d.]+" height="[\d.]+"/,m=>m.replace(/[\d.]+/g,x=>Math.round(x*.6))),v})),a:ord.indexOf(n),sol:`Hình đúng có ${n} khối.`,kind:'Đếm khối lập phương'}},
 lr:()=>()=>{const L=shuf(OBJ1).slice(0,3),k=R(0,2),left=Math.random()<.5;if((left&&k===0)||(!left&&k===2))return QP1.lr()();const t=left?L[k-1]:L[k+1];const o=shuf(L.filter(x=>x!==L[k]));return{type:'opt',cols:2,q:`Vật nào ở <b>bên ${left?'trái':'phải'}</b> ${L[k][1]}?`,say:`Vật nào ở ngay bên ${left?'trái':'phải'} ${L[k][1]}?`,pic:`<div class="g1grp">${L.map(x=>spr(x[0],46)).join('')}</div>`,opts:o.map(x=>({h:spr(x[0],44),v:x[0]})),a:o.indexOf(t),sol:`Bên ${left?'trái':'phải'} ${L[k][1]} là ${t[1]}.`,kind:'Bên trái, bên phải'}},
 ud:()=>()=>{const [a,b]=shuf(OBJ1).slice(0,2),up=Math.random()<.5;return{type:'opt',cols:2,q:`${a[1].charAt(0).toUpperCase()+a[1].slice(1)} ở trên hay ở dưới ${b[1]}?`,say:`${a[1]} ở trên hay ở dưới ${b[1]}?`,pic:`<div class="g1grp" style="flex-direction:column;align-items:center">${up?spr(a[0],46)+spr(b[0],46):spr(b[0],46)+spr(a[0],46)}</div>`,opts:[{h:'Ở trên',v:1},{h:'Ở dưới',v:0}],a:up?0:1,sol:`${a[1]} ở ${up?'trên':'dưới'} ${b[1]}.`,kind:'Trên, dưới'}},
 nth:()=>()=>{const L=Array.from({length:5},()=>pick(OBJ1));const k=R(0,4),[s,w]=pick(OBJ1.filter(x=>!L.some(y=>y[0]===x[0])));L[k]=[s,w];const fromL=Math.random()<.5;const n=fromL?k+1:5-k;return OQ(`Tính từ bên ${fromL?'trái':'phải'}, ${w} đứng thứ mấy?`,`Tính từ bên ${fromL?'trái':'phải'} sang, ${w} đứng thứ mấy?`,n,1,5,`Đếm từ bên ${fromL?'trái':'phải'}: ${w} đứng thứ ${n}.`,'Vị trí, thứ tự',`<div class="g1grp">${L.map(x=>spr(x[0],40)).join('')}</div>`)},
 posTF:()=>()=>{const L=shuf(OBJ1).slice(0,3),i=R(0,1),truth=Math.random()<.5;const [a,b]=truth?[L[i],L[i+1]]:[L[i+1],L[i]];return{type:'tf',q:`${a[1].charAt(0).toUpperCase()+a[1].slice(1)} ở bên trái ${b[1]}. Đúng hay sai?`,say:`${a[1]} ở bên trái ${b[1]}. Đúng hay sai?`,pic:`<div class="g1grp">${L.map(x=>spr(x[0],46)).join('')}</div>`,a:truth,sol:truth?'Đúng.':'Sai.',kind:'Bên trái, bên phải'}},
};
/* ---------- LỚP 2 ---------- */
const QC2={
 add21:()=>()=>{const a=R(1,8)*10+R(2,9),b=R(10-a%10,9);return NQ(`<b>${a} + ${b} = ?</b>`,`${a} cộng ${b} bằng bao nhiêu?`,a+b,`${a%10} + ${b} = ${a%10+b}, viết ${(a+b)%10} nhớ 1; ${Math.floor(a/10)} thêm 1 bằng ${Math.floor((a+b)/10)}. Kết quả ${a+b}.`,'Cộng có nhớ (2 chữ số + 1 chữ số)')},
 add22:()=>()=>{let a,b;do{a=R(11,79);b=R(11,89-a)}while(a%10+b%10<10||a+b>100);return{...NQ('Đặt tính rồi tính:','Đặt tính rồi tính. Kết quả là bao nhiêu?',a+b,`Cộng hàng đơn vị: ${a%10} + ${b%10} = ${a%10+b%10}, viết ${(a+b)%10} nhớ 1. Kết quả ${a+b}.`,'Cộng có nhớ (2 chữ số + 2 chữ số)'),pic:`<div class="g1grp">${colPic(a,'+',b)}</div>`}},
 sub21:()=>()=>{const a=R(2,9)*10+R(0,8),b=R(a%10+1,9);return NQ(`<b>${a} − ${b} = ?</b>`,`${a} trừ ${b} bằng bao nhiêu?`,a-b,`${a%10} không trừ được ${b}, lấy ${a%10+10} − ${b} = ${a%10+10-b}, viết ${(a-b)%10} nhớ 1. Kết quả ${a-b}.`,'Trừ có nhớ (2 chữ số − 1 chữ số)')},
 sub22:()=>()=>{let a,b;do{a=R(21,99);b=R(11,a-1)}while(a%10>=b%10||Math.floor(b/10)>=Math.floor(a/10));return{...NQ('Đặt tính rồi tính:','Đặt tính rồi tính. Kết quả là bao nhiêu?',a-b,`${a%10} không trừ được ${b%10}, lấy ${a%10+10} − ${b%10} = ${a%10+10-b%10}, viết ${(a-b)%10} nhớ 1. Kết quả ${a-b}.`,'Trừ có nhớ (2 chữ số − 2 chữ số)'),pic:`<div class="g1grp">${colPic(a,'−',b)}</div>`}},
 match:(op)=>()=>{const mk=()=>{if(op==='+'){let a,b;do{a=R(11,79);b=R(2,89-a)}while(a%10+b%10<10);return[`${a} + ${b}`,a+b]}let a,b;do{a=R(21,99);b=R(2,a-5)}while(a%10>=b%10);return[`${a} − ${b}`,a-b]};const t=mk(),L=[t];while(L.length<3){const e=mk();if(!L.some(x=>x[1]===e[1]))L.push(e)}const o=shuf(L);return{type:'opt',cols:3,q:`Phép tính nào có kết quả bằng <b>${t[1]}</b>?`,say:`Phép tính nào có kết quả bằng ${t[1]}?`,opts:o.map(x=>({h:x[0],v:x[1]})),a:o.indexOf(t),sol:o.map(x=>`${x[0]} = ${x[1]}`).join('; ')+'.',kind:'Nối phép tính với kết quả'}},
 miss:()=>()=>{let a,b;do{a=R(11,79);b=R(2,89-a)}while(a%10+b%10<10);const c=a+b;return Math.random()<.5?NQ(`<b>${a} + ☐ = ${c}</b>`,`${a} cộng mấy bằng ${c}?`,b,`☐ = ${c} − ${a} = ${b}.`,'Tìm số hạng'):NQ(`<b>${c} − ☐ = ${a}</b>`,`${c} trừ mấy bằng ${a}?`,b,`☐ = ${c} − ${a} = ${b}.`,'Tìm số trừ')},
 cmp:()=>()=>{const a=R(15,60),b=R(6,30),c=R(20,90),d=R(5,15);return SG(0,0,`${a} + ${b}`,`${c} − ${d}`,'So sánh kết quả phép tính',a+b,c-d)},
 word:(op)=>()=>{const t=R(0,2);if(op==='+'){if(t===0){const a=R(25,60),b=R(6,9);return WQ(`Trong hộp có ${a} chiếc bút chì màu. Mẹ mua thêm ${b} chiếc nữa. Hỏi trong hộp có tất cả bao nhiêu chiếc bút?`,`Hộp có ${a} chiếc bút, mua thêm ${b} chiếc. Có tất cả bao nhiêu?`,a+b,`${a} + ${b} = ${a+b} (chiếc).`)}if(t===1){const a=R(30,55),b=R(15,38);return WQ(`Con lợn đen nặng ${a} kg. Con lợn trắng nặng hơn con lợn đen ${b} kg. Hỏi con lợn trắng nặng bao nhiêu ki-lô-gam?`,`Lợn đen nặng ${a} ki-lô-gam, lợn trắng nặng hơn ${b} ki-lô-gam. Lợn trắng nặng bao nhiêu?`,a+b,`${a} + ${b} = ${a+b} (kg).`)}const a=R(18,45),b=R(17,45);return WQ(`Lớp 2A gấp được ${a} ngôi sao, lớp 2B gấp được ${b} ngôi sao. Hỏi cả hai lớp gấp được bao nhiêu ngôi sao?`,`Lớp 2A gấp ${a}, lớp 2B gấp ${b} ngôi sao. Cả hai lớp gấp được bao nhiêu?`,a+b,`${a} + ${b} = ${a+b} (ngôi sao).`)}if(t===0){const a=R(35,48),b=R(26,a-1);return WQ(`Năm nay bố ${a} tuổi, mẹ ${b} tuổi. Hỏi bố hơn mẹ bao nhiêu tuổi?`,`Bố ${a} tuổi, mẹ ${b} tuổi. Bố hơn mẹ bao nhiêu tuổi?`,a-b>0?a-b:b-a,`${Math.max(a,b)} − ${Math.min(a,b)} = ${Math.abs(a-b)} (tuổi).`)}if(t===1){const a=R(62,95),b=R(25,58);return WQ(`Xe ô tô chở được ${a} kg táo. Xe máy chở được ${b} kg táo. Hỏi xe ô tô chở nhiều hơn xe máy bao nhiêu ki-lô-gam táo?`,`Ô tô chở ${a} ki-lô-gam, xe máy chở ${b} ki-lô-gam. Ô tô chở nhiều hơn bao nhiêu?`,a-b,`${a} − ${b} = ${a-b} (kg).`)}const a=R(32,90),b=R(5,9);return WQ(`Một con ốc sên muốn bò lên ngọn cây cao ${a} dm. Ốc sên đã bò được ${a-b} dm. Hỏi ốc sên còn phải bò bao nhiêu đề-xi-mét nữa?`,`Cây cao ${a} đề-xi-mét, ốc sên đã bò ${a-b}. Còn phải bò bao nhiêu?`,b,`${a} − ${a-b} = ${b} (dm).`)},
};
function lineSvg(k){const W=220,H=90;if(k==='seg')return`<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" aria-hidden="true"><line x1="30" y1="60" x2="190" y2="30" stroke="#1F2A5A" stroke-width="4"/><rect x="26" y="56" width="8" height="8" fill="#F04A1B"/><rect x="186" y="26" width="8" height="8" fill="#F04A1B"/><text x="22" y="84" font-size="15" font-weight="700" fill="#1F2A5A">A</text><text x="188" y="20" font-size="15" font-weight="700" fill="#1F2A5A">B</text></svg>`;if(k==='line')return`<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" aria-hidden="true"><line x1="0" y1="72" x2="${W}" y2="18" stroke="#1F2A5A" stroke-width="4"/><rect x="66" y="56" width="8" height="8" fill="#F04A1B"/><rect x="146" y="36" width="8" height="8" fill="#F04A1B"/><text x="62" y="84" font-size="15" font-weight="700" fill="#1F2A5A">A</text><text x="148" y="28" font-size="15" font-weight="700" fill="#1F2A5A">B</text></svg>`;return`<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" aria-hidden="true"><path d="M20 60 C 60 0, 100 100, 140 40 S 190 30, 205 55" fill="none" stroke="#1F2A5A" stroke-width="4"/></svg>`}
function ptsSvg(ok){const P=ok?[[30,70],[110,48],[190,26]]:[[30,70],[110,R(0,1)?20:76],[190,30]];return`<svg viewBox="0 0 220 96" width="220" height="96" aria-hidden="true">${ok?'':''}${P.map((p,i)=>`<rect x="${p[0]-5}" y="${p[1]-5}" width="10" height="10" fill="#F04A1B"/><text x="${p[0]-5}" y="${p[1]+22}" font-size="15" font-weight="700" fill="#1F2A5A">${'ABC'[i]}</text>`).join('')}</svg>`}
function zigSvg(L){const n=L.length,W=60+n*60;let x=20,y=70,pts=[[x,y]];L.forEach((l,i)=>{x+=60;y=i%2?70:20;pts.push([x,y])});const N='ABCDEFG';return`<svg viewBox="0 0 ${W} 100" width="${Math.min(300,W)}" height="${Math.min(300,W)*100/W}" aria-hidden="true"><polyline points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#1F2A5A" stroke-width="4"/>${pts.map((p,i)=>`<rect x="${p[0]-4}" y="${p[1]-4}" width="8" height="8" fill="#F04A1B"/><text x="${p[0]-5}" y="${p[1]>40?p[1]+22:p[1]-8}" font-size="14" font-weight="700" fill="#1F2A5A">${N[i]}</text>`).join('')}${L.map((l,i)=>`<text x="${(pts[i][0]+pts[i+1][0])/2+6}" y="${(pts[i][1]+pts[i+1][1])/2+4}" font-size="13" fill="#0B7FB8">${l}cm</text>`).join('')}</svg>`}
function rulerSvg(L){const u=24,W=u*10+24;let o='';for(let i=0;i<=10;i++){o+=`<line x1="${12+i*u}" y1="48" x2="${12+i*u}" y2="${i%5?60:66}" stroke="#1F2A5A" stroke-width="2"/><text x="${12+i*u}" y="82" text-anchor="middle" font-size="12" fill="#1F2A5A">${i}</text>`}return`<svg viewBox="0 0 ${W} 90" width="${W}" height="90" aria-hidden="true"><rect x="2" y="44" width="${W-4}" height="44" fill="#FDE08A" stroke="#1F2A5A" stroke-width="2"/>${o}<line x1="12" y1="24" x2="${12+L*u}" y2="24" stroke="#F04A1B" stroke-width="5"/><rect x="8" y="20" width="8" height="8" fill="#1F2A5A"/><rect x="${8+L*u}" y="20" width="8" height="8" fill="#1F2A5A"/></svg>`}
function stripSvg(k){const W=200,H=80,w=(W-8)/(k+1);let o=`<rect x="4" y="4" width="${W-8}" height="${H-8}" fill="#E6F4FD" stroke="#1F2A5A" stroke-width="4"/>`;for(let i=1;i<=k;i++)o+=`<line x1="${4+i*w}" y1="4" x2="${4+i*w}" y2="${H-4}" stroke="#1F2A5A" stroke-width="4"/>`;return`<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" aria-hidden="true">${o}</svg>`}
const QG2={
 line:()=>()=>{const k=pick(['seg','line','curve']),N={seg:'Đoạn thẳng AB',line:'Đường thẳng AB',curve:'Đường cong'};const o=['seg','line','curve'];return{type:'opt',cols:3,q:'Hình dưới đây là gì?',say:'Hình dưới đây là đoạn thẳng, đường thẳng hay đường cong?',pic:`<div class="g1grp">${lineSvg(k)}</div>`,opts:o.map(v=>({h:N[v],v})),a:o.indexOf(k),sol:{seg:'Đoạn thẳng có hai đầu mút A và B.',line:'Đường thẳng kéo dài mãi về hai phía.',curve:'Đây là đường cong.'}[k],kind:'Đoạn thẳng, đường thẳng, đường cong'}},
 col:()=>()=>{const ok=Math.random()<.5;return{type:'tf',q:'Ba điểm A, B, C thẳng hàng. Đúng hay sai?',say:'Ba điểm A, B, C có thẳng hàng không? Đúng hay sai?',pic:`<div class="g1grp">${ptsSvg(ok)}</div>`,a:ok,sol:ok?'Ba điểm cùng nằm trên một đường thẳng.':'Ba điểm không cùng nằm trên một đường thẳng.',kind:'Ba điểm thẳng hàng'}},
 measure:()=>()=>{const L=R(2,10);return OQ('Đoạn thẳng màu đỏ dài mấy xăng-ti-mét?','Nhìn thước, đoạn thẳng màu đỏ dài mấy xăng-ti-mét?',L,1,10,`Đầu đoạn thẳng ở vạch 0, cuối ở vạch ${L}: dài ${L} cm.`,'Đo độ dài đoạn thẳng',`<div class="g1grp">${rulerSvg(L)}</div>`)},
 segs:()=>()=>{const n=R(3,4);return OQ(`Trên một đường thẳng có ${n} điểm. Có tất cả bao nhiêu đoạn thẳng có hai đầu là hai trong ${n} điểm đó?`,`Có ${n} điểm trên một đường thẳng. Có bao nhiêu đoạn thẳng?`,n*(n-1)/2,1,10,n===3?'Ba điểm A, B, C: AB, BC, AC, có 3 đoạn.':'Bốn điểm A, B, C, D: AB, AC, AD, BC, BD, CD, có 6 đoạn.','Đếm đoạn thẳng')},
 zig:()=>()=>{const L=Array.from({length:R(2,4)},()=>R(2,9)),s=L.reduce((a,b)=>a+b,0);return{...NQ('Tính độ dài đường gấp khúc.','Tính độ dài đường gấp khúc bằng cách cộng độ dài các đoạn thẳng.',s,`${L.join(' + ')} = ${s} (cm).`,'Độ dài đường gấp khúc'),pic:`<div class="g1grp">${zigSvg(L)}</div>`}},
 zigN:()=>()=>{const n=R(3,6),N='ABCDEFG'.slice(0,n);return OQ(`Đường gấp khúc ${N.split('').join('')} gồm mấy đoạn thẳng?`,`Đường gấp khúc ${N.split('').join(' ')} gồm mấy đoạn thẳng?`,n-1,1,8,`${n} điểm nối liền nhau tạo thành ${n-1} đoạn thẳng.`,'Đường gấp khúc')},
 quad:()=>()=>{const k=pick([1,1,2]);return OQ('Trong hình dưới đây có bao nhiêu hình tứ giác?','Hình chữ nhật được chia bởi các đoạn thẳng. Có tất cả bao nhiêu hình tứ giác?',(k+1)*(k+2)/2,1,8,k===1?'Có 2 hình nhỏ và 1 hình lớn: 3 hình tứ giác.':'Có 3 hình nhỏ, 2 hình ghép đôi, 1 hình lớn: 6 hình tứ giác.','Đếm hình tứ giác',`<div class="g1grp">${stripSvg(k)}</div>`)},
 quadPick:()=>()=>{const ks=shuf(['tri','quad','quad','rect','tri','sq']);return{type:'pick',q:'Chạm vào <b>tất cả</b> hình tứ giác.',say:'Hình tứ giác có bốn cạnh. Chạm vào tất cả hình tứ giác rồi bấm kiểm tra.',opts:ks.map(k=>polySvg(k,52)),a:ks.map((k,i)=>k!=='tri'?i:-1).filter(i=>i>=0),sol:'Hình có 4 cạnh là hình tứ giác (kể cả hình chữ nhật, hình vuông).',kind:'Hình tứ giác'}},
 pots:()=>()=>CQ('Mai muốn đặt 5 chậu cây thành 2 hàng, mỗi hàng có 3 chậu. Cách nào làm được?','Năm chậu cây xếp thành hai hàng, mỗi hàng ba chậu. Cách nào làm được?','Xếp hai hàng cắt nhau, chậu ở giữa dùng chung',['Không thể xếp được','Xếp 5 chậu thành một hàng dài','Xếp mỗi hàng 3 chậu riêng biệt'],'Hai hàng chung nhau 1 chậu: 3 + 3 − 1 = 5.','Xếp hình, suy luận'),
};
/* ---------- LỚP 3 ---------- */
const QN3={
 mul:()=>()=>{const a=R(11,49),b=R(2,Math.min(9,Math.floor(99/a)||2));const v=a*b;return v>99?QN3.mul()():NQ(`<b>${a} × ${b} = ?</b>`,`${a} nhân ${b} bằng bao nhiêu?`,v,`${a} × ${b} = ${v}.`,'Nhân số có hai chữ số với số có một chữ số')},
 mulCol:()=>()=>{const a=R(12,48),b=R(2,4),v=a*b;return{...NQ('Đặt tính rồi tính:','Đặt tính rồi tính. Kết quả là bao nhiêu?',v,`Nhân từ hàng đơn vị: ${b} × ${a%10} = ${b*(a%10)}${b*(a%10)>=10?`, viết ${b*(a%10)%10} nhớ ${Math.floor(b*(a%10)/10)}`:''}; ${b} × ${Math.floor(a/10)} = ${b*Math.floor(a/10)}${b*(a%10)>=10?`, thêm ${Math.floor(b*(a%10)/10)}`:''}. Kết quả ${v}.`,'Nhân số có hai chữ số với số có một chữ số'),pic:`<div class="g1grp">${colPic(a,'×',b)}</div>`}},
 mulPick:()=>()=>{const t=pick([84,96,72,90,60,48]);const L=[];const ds=[2,3,4,6].filter(d=>t%d===0&&t/d>=10&&t/d<=99);ds.slice(0,2).forEach(d=>L.push([`${t/d} × ${d}`,t]));while(L.length<6){const a=R(11,45),b=R(2,4);if(a*b!==t&&a*b<100&&!L.some(x=>x[0]===`${a} × ${b}`))L.push([`${a} × ${b}`,a*b])}const o=shuf(L);return{type:'pick',q:`Chạm vào <b>tất cả</b> phép tính có kết quả là ${t}.`,say:`Chạm vào tất cả phép tính có kết quả là ${t}, rồi bấm kiểm tra.`,opts:o.map(x=>x[0]),a:o.map((x,i)=>x[1]===t?i:-1).filter(i=>i>=0),sol:o.map(x=>`${x[0]} = ${x[1]}`).join('; ')+'.',kind:'Nhân số có hai chữ số với số có một chữ số'}},
 times:()=>()=>{const a=R(3,12),k=R(2,8);return Math.random()<.5?CQ(`Gấp ${a} lên ${k} lần được:`,`Gấp ${a} lên ${k} lần được bao nhiêu?`,String(a*k),[String(a+k),String(a*k+k),String(a*(k+1))],`Gấp lên ${k} lần: ${a} × ${k} = ${a*k}.`,'Gấp một số lên một số lần',1):WQ(`Mai có ${a} cái kẹo. Số kẹo của Nam gấp ${k} lần số kẹo của Mai. Hỏi Nam có bao nhiêu cái kẹo?`,`Mai có ${a} cái kẹo, Nam gấp ${k} lần. Nam có bao nhiêu?`,a*k,`${a} × ${k} = ${a*k} (cái kẹo).`)},
 reduce:()=>()=>{const k=R(2,9),q=R(2,11),a=k*q;return Math.random()<.5?CQ(`Giảm ${a} đi ${k} lần được:`,`Giảm ${a} đi ${k} lần được bao nhiêu?`,String(q),[String(a-k),String(a*k),String(q+1)],`Giảm đi ${k} lần: ${a} : ${k} = ${q}.`,'Giảm một số đi một số lần',1):WQ(`Thư viện có ${a} cuốn sách. Sau khi cho mượn, số sách còn lại giảm đi ${k} lần. Hỏi thư viện còn lại bao nhiêu cuốn sách?`,`Thư viện có ${a} cuốn, số sách giảm đi ${k} lần. Còn lại bao nhiêu?`,q,`${a} : ${k} = ${q} (cuốn).`)},
 rem:()=>()=>{const d=R(3,9),q=R(2,9),r=R(0,d-1),a=d*q+r;return Math.random()<.5?NQ(`<b>${a} : ${d} = ${q} (dư ☐)</b>`,`${a} chia ${d} được ${q}, dư bao nhiêu?`,r,`${d} × ${q} = ${d*q}; ${a} − ${d*q} = ${r}.`,'Phép chia có dư'):NQ(`<b>${a} : ${d} = ☐ (dư ${r})</b>`,`${a} chia ${d} được bao nhiêu, dư ${r}?`,q,`${d} × ${q} = ${d*q}; ${d*q} + ${r} = ${a}.`,'Phép chia có dư')},
 remPick:()=>()=>{const r=R(1,4),L=[];while(L.length<6){const d=R(r+1,9),q=R(2,9),rr=L.length<2?r:R(0,d-1);const e=[`${d*q+rr} : ${d}`,rr];if(!L.some(x=>x[0]===e[0]))L.push(e)}const o=shuf(L);return{type:'pick',q:`Chạm vào <b>tất cả</b> phép chia có số dư là ${r}.`,say:`Chạm vào tất cả phép chia có số dư là ${r}, rồi bấm kiểm tra.`,opts:o.map(x=>x[0]),a:o.map((x,i)=>x[1]===r?i:-1).filter(i=>i>=0),sol:o.map(x=>`${x[0]} dư ${x[1]}`).join('; ')+'.',kind:'Phép chia có dư'}},
 div:()=>()=>{const d=R(2,4),q=pick([11,12,13,21,22,23,31,32,14,24,16,19,25]);const a=d*q;return a>99?QN3.div()():NQ(`<b>${a} : ${d} = ?</b>`,`${a} chia ${d} bằng bao nhiêu?`,q,`${a} : ${d} = ${q} vì ${q} × ${d} = ${a}.`,'Chia số có hai chữ số cho số có một chữ số')},
 divW:()=>()=>{const d=R(2,6),q=R(8,16),a=d*q;return a>99?QN3.divW()():WQ(`Thầy giáo xếp đều ${a} học sinh vào ${d} phòng thi. Hỏi mỗi phòng có bao nhiêu học sinh?`,`${a} học sinh xếp đều vào ${d} phòng. Mỗi phòng bao nhiêu học sinh?`,q,`${a} : ${d} = ${q} (học sinh).`)},
 mulW:()=>()=>{const a=R(11,24),b=R(2,4);return WQ(`Mỗi lớp học võ có ${a} bạn. Hỏi ${b} lớp như vậy có bao nhiêu bạn?`,`Mỗi lớp có ${a} bạn. ${b} lớp có bao nhiêu bạn?`,a*b,`${a} × ${b} = ${a*b} (bạn).`)},
 two:()=>()=>{const t=R(0,2);if(t===0){const a=R(8,20),b=R(2,6);return NQ(`Can thứ nhất đựng ${a} lít nước mắm. Can thứ hai đựng ít hơn can thứ nhất ${b} lít. Hỏi cả hai can đựng bao nhiêu lít nước mắm?`,`Can một ${a} lít, can hai ít hơn ${b} lít. Cả hai can bao nhiêu lít?`,a+a-b,`Can hai: ${a} − ${b} = ${a-b} (l). Cả hai: ${a} + ${a-b} = ${2*a-b} (l).`,'Toán lời văn hai bước')}if(t===1){const a=R(12,30),k=R(2,3);return NQ(`Lớp 3A thu gom được ${a} kg giấy vụn. Lớp 3B thu gom được gấp ${k} lần lớp 3A. Hỏi cả hai lớp thu gom được bao nhiêu ki-lô-gam giấy vụn?`,`Lớp 3A thu ${a} ki-lô-gam, lớp 3B gấp ${k} lần. Cả hai lớp thu bao nhiêu?`,a+a*k,`3B: ${a} × ${k} = ${a*k} (kg). Cả hai: ${a} + ${a*k} = ${a+a*k} (kg).`,'Toán lời văn hai bước')}const x=R(12,30),k=R(2,4);return NQ(`Vườn nhà cô Lan có ${x*k} cây xoài. Số cây ổi bằng số cây xoài giảm đi ${k} lần. Hỏi vườn có tất cả bao nhiêu cây xoài và ổi?`,`Có ${x*k} cây xoài, số cây ổi bằng số xoài giảm ${k} lần. Tất cả bao nhiêu cây?`,x*k+x,`Ổi: ${x*k} : ${k} = ${x} (cây). Tất cả: ${x*k} + ${x} = ${x*k+x} (cây).`,'Toán lời văn hai bước')},
};
function thermoSvg(t){const H=150,top=14,bot=120,ty=bot-(t+10)/50*(bot-top);let o='';for(let v=-10;v<=40;v+=10){const y=bot-(v+10)/50*(bot-top);o+=`<line x1="44" y1="${y}" x2="54" y2="${y}" stroke="#1F2A5A" stroke-width="2"/><text x="58" y="${y+4}" font-size="11" fill="#1F2A5A">${v}</text>`}return`<svg viewBox="0 0 90 ${H}" width="90" height="${H}" aria-hidden="true"><rect x="32" y="${top-4}" width="12" height="${bot-top+8}" fill="#fff" stroke="#1F2A5A" stroke-width="3"/><rect x="35" y="${ty}" width="6" height="${bot-ty+4}" fill="#F04A1B"/><rect x="28" y="${bot+2}" width="20" height="20" fill="#F04A1B" stroke="#1F2A5A" stroke-width="3"/>${o}</svg>`}
const QU3={
 mm:()=>()=>{const t=R(0,3);if(t===0){const a=R(2,15);return NQ(`<b>${a} cm = ? mm</b>`,`${a} xăng-ti-mét bằng bao nhiêu mi-li-mét?`,a*10,`1 cm = 10 mm, nên ${a} cm = ${a*10} mm.`,'Đổi đơn vị mi-li-mét')}if(t===1){const a=R(2,9);return NQ(`<b>${a*10} mm = ? cm</b>`,`${a*10} mi-li-mét bằng bao nhiêu xăng-ti-mét?`,a,`${a*10} : 10 = ${a} (cm).`,'Đổi đơn vị mi-li-mét')}if(t===2){const a=R(1,9),b=R(1,9);return NQ(`<b>${a} cm ${b} mm = ? mm</b>`,`${a} xăng-ti-mét ${b} mi-li-mét bằng bao nhiêu mi-li-mét?`,a*10+b,`${a} cm = ${a*10} mm; ${a*10} + ${b} = ${a*10+b} (mm).`,'Đổi đơn vị mi-li-mét')}return CQ('<b>1 m = ? mm</b>','Một mét bằng bao nhiêu mi-li-mét?','1 000',['100','10','10 000'],'1 m = 1 000 mm.','Đổi đơn vị mi-li-mét',1)},
 mmCalc:()=>()=>{const a=R(20,90),b=R(10,a-5),add=Math.random()<.5;return add?NQ(`<b>${a} mm + ${b} mm = ? mm</b>`,`${a} mi-li-mét cộng ${b} mi-li-mét bằng bao nhiêu?`,a+b,`${a} + ${b} = ${a+b} (mm).`,'Tính với đơn vị đo'):NQ(`<b>${a} mm − ${b} mm = ? mm</b>`,`${a} mi-li-mét trừ ${b} mi-li-mét bằng bao nhiêu?`,a-b,`${a} − ${b} = ${a-b} (mm).`,'Tính với đơn vị đo')},
 g:()=>()=>{const t=R(0,2);if(t===0){const a=R(1,5);return CQ(`<b>${a} kg = ? g</b>`,`${a} ki-lô-gam bằng bao nhiêu gam?`,fN(a*1000),[fN(a*100),fN(a*10),fN(a*10000)],`1 kg = 1 000 g.`,'Đổi đơn vị gam',1)}if(t===1){const a=R(1,4),b=R(1,9)*100;return CQ(`<b>${a} kg ${b} g = ? g</b>`,`${a} ki-lô-gam ${b} gam bằng bao nhiêu gam?`,fN(a*1000+b),[fN(a*100+b),String(a)+String(b),fN(a*1000+b*10)].filter(x=>x!==fN(a*1000+b)),`${a} kg = ${fN(a*1000)} g; ${fN(a*1000)} + ${b} = ${fN(a*1000+b)} (g).`,'Đổi đơn vị gam',1)}const a=R(1,9)*50,b=R(1,9)*25;return NQ(`<b>${a} g + ${b} g = ? g</b>`,`${a} gam cộng ${b} gam bằng bao nhiêu gam?`,a+b,`${a} + ${b} = ${a+b} (g).`,'Tính với đơn vị gam')},
 ml:()=>()=>{const t=R(0,2);if(t===0){const a=R(1,5);return CQ(`<b>${a} l = ? ml</b>`,`${a} lít bằng bao nhiêu mi-li-lít?`,fN(a*1000),[fN(a*100),fN(a*10),fN(a*10000)],'1 l = 1 000 ml.','Đổi đơn vị mi-li-lít',1)}if(t===1){const c=pick([200,250,500]),n=R(2,1000/c-1);return WQ(`Bình có 1 l nước. Rót ra ${n} cốc, mỗi cốc ${c} ml. Hỏi trong bình còn lại bao nhiêu mi-li-lít nước?`,`Bình 1 lít rót ra ${n} cốc, mỗi cốc ${c} mi-li-lít. Còn lại bao nhiêu mi-li-lít?`,1000-n*c,`Đã rót: ${c} × ${n} = ${n*c} (ml). Còn: 1 000 − ${n*c} = ${1000-n*c} (ml).`)}const a=R(1,9)*100,b=R(1,9)*50;return NQ(`<b>${a} ml + ${b} ml = ? ml</b>`,`${a} mi-li-lít cộng ${b} mi-li-lít bằng bao nhiêu?`,a+b,`${a} + ${b} = ${a+b} (ml).`,'Tính với đơn vị mi-li-lít')},
 temp:()=>()=>{const t=R(0,7)*5;return OQ('Nhiệt kế chỉ bao nhiêu độ C?','Quan sát nhiệt kế. Nhiệt kế chỉ bao nhiêu độ C?',t,0,40,`Cột đỏ dừng ở vạch ${t}: ${t} °C.`,'Đọc nhiệt kế',`<div class="g1grp">${thermoSvg(t)}</div>`)},
 tempF:()=>()=>{const c=pick([['Nhiệt độ của nước đá đang tan','0 °C'],['Nhiệt độ cơ thể người khỏe mạnh','37 °C'],['Nhiệt độ của nước đang sôi','100 °C'],['Nhiệt độ phòng học mát mẻ','25 °C']]);return CQ(`<b>${c[0]}</b> khoảng bao nhiêu?`,`${c[0]} khoảng bao nhiêu độ C?`,c[1],['0 °C','37 °C','100 °C','25 °C'].filter(x=>x!==c[1]),`${c[0]} khoảng ${c[1]}.`,'Nhiệt độ',1)},
 unit:()=>()=>{const c=pick([['Quả trứng gà nặng khoảng 50 …','g'],['Bao gạo nặng 25 …','kg'],['Chai nước mắm chứa 500 …','ml'],['Can dầu chứa 5 …','l'],['Bề dày quyển vở khoảng 5 …','mm'],['Chiều dài bàn học khoảng 12 …','dm'],['Quả táo nặng khoảng 200 …','g'],['Thìa cà phê chứa khoảng 5 …','ml']]);return CQ(`Chọn đơn vị thích hợp: <b>${c[0]}</b>`,`${c[0].replace('…','')}. Đơn vị nào thích hợp?`,c[1],['g','kg','ml','l','mm','dm'].filter(x=>x!==c[1]).sort(()=>Math.random()-.5).slice(0,3),`${c[0].replace('…',c[1])}.`,'Chọn đơn vị đo',1)},
 grow:()=>()=>{const a=R(3,9),b=R(2,8);return WQ(`Một chồi non mọc trên thân cây. Ngày thứ nhất chồi non dài ${a} mm. Ngày thứ hai chồi dài thêm ${b} mm. Hỏi sau hai ngày chồi non dài bao nhiêu mi-li-mét?`,`Ngày một chồi dài ${a} mi-li-mét, ngày hai dài thêm ${b}. Sau hai ngày dài bao nhiêu?`,a+b,`${a} + ${b} = ${a+b} (mm).`)},
};
/* ---------- LỚP 4 ---------- */
const QM4={
 mass:()=>()=>{const c=pick([['yến','kg',10],['tạ','kg',100],['tấn','kg',1000],['tấn','tạ',10],['tạ','yến',10],['tấn','yến',100]]),a=R(2,9);return CQ(`<b>${a} ${c[0]} = ? ${c[1]}</b>`,`${a} ${c[0]} bằng bao nhiêu ${c[1]}?`,fN(a*c[2]),[fN(a*c[2]*10),fN(a*c[2]/10),fN(a*c[2]*100)].filter(x=>!/\./.test(x)),`1 ${c[0]} = ${fN(c[2])} ${c[1]}, nên ${a} ${c[0]} = ${fN(a*c[2])} ${c[1]}.`,'Yến, tạ, tấn',1)},
 massMix:()=>()=>{const c=pick([['tấn','kg',1000],['tạ','kg',100],['yến','kg',10]]),a=R(1,9),b=R(1,c[2]-1);return CQ(`<b>${a} ${c[0]} ${b} kg = ? kg</b>`,`${a} ${c[0]} ${b} ki-lô-gam bằng bao nhiêu ki-lô-gam?`,fN(a*c[2]+b),[fN(Number(`${a}${b}`)),fN(a*c[2]*10+b),fN((a+b)*c[2])].filter(x=>x!==fN(a*c[2]+b)),`${a} ${c[0]} = ${fN(a*c[2])} kg; ${fN(a*c[2])} + ${b} = ${fN(a*c[2]+b)} (kg).`,'Yến, tạ, tấn',1)},
 massCalc:()=>()=>{const u=pick(['yến','tạ','tấn']),a=R(12,80),b=R(5,a-2),add=Math.random()<.5;return add?NQ(`<b>${a} ${u} + ${b} ${u} = ? ${u}</b>`,`${a} ${u} cộng ${b} ${u} bằng bao nhiêu ${u}?`,a+b,`${a} + ${b} = ${a+b} (${u}).`,'Tính với yến, tạ, tấn'):NQ(`<b>${a} ${u} × 3 = ? ${u}</b>`,`${a} ${u} nhân 3 bằng bao nhiêu ${u}?`,a*3,`${a} × 3 = ${a*3} (${u}).`,'Tính với yến, tạ, tấn')},
 area:()=>()=>{const c=pick([['dm²','cm²',100],['m²','dm²',100],['cm²','mm²',100],['m²','cm²',10000]]),a=R(2,30);return CQ(`<b>${a} ${c[0]} = ? ${c[1]}</b>`,`${a} ${DUN[c[0]]} bằng bao nhiêu ${DUN[c[1]]}?`,fN(a*c[2]),[fN(a*c[2]*10),fN(a*c[2]/10),fN(a*10)].filter(x=>!/\./.test(x)&&x!==fN(a*c[2])),`1 ${c[0]} = ${fN(c[2])} ${c[1]}.`,'Đề-xi-mét vuông, mét vuông, mi-li-mét vuông',1)},
 areaRead:()=>()=>{const n=R(12,999),u=pick(['dm²','m²','mm²']);const w=`${vnRead(n)} ${DUN[u]}`;return CQ(`"<b>${w}</b>" viết là:`,`${w} viết là gì?`,`${n} ${u}`,[`${n} ${u.replace('²','')}`,...['dm²','m²','mm²'].filter(x=>x!==u).map(x=>`${n} ${x}`)],`${w}: ${n} ${u}.`,'Đọc, viết số đo diện tích',1)},
 areaObj:()=>()=>{const c=pick([['Mặt bàn học','50 dm²'],['Phòng ngủ','15 m²'],['Con tem thư','6 cm²'],['Đầu bút chì','4 mm²'],['Sân trường','800 m²'],['Bìa quyển vở','4 dm²']]);return CQ(`<b>${c[0]}</b> có diện tích khoảng bao nhiêu?`,`${c[0]} có diện tích khoảng bao nhiêu trong thực tế?`,c[1],['50 dm²','15 m²','6 cm²','4 mm²','800 m²','4 dm²'].filter(x=>x!==c[1]).sort(()=>Math.random()-.5).slice(0,3),`${c[0]} khoảng ${c[1]}.`,'Ước lượng diện tích',1)},
 time:()=>()=>{const t=R(0,3);if(t===0){const a=R(2,9);return NQ(`<b>${a} phút = ? giây</b>`,`${a} phút bằng bao nhiêu giây?`,a*60,`1 phút = 60 giây; ${a} × 60 = ${a*60}.`,'Giây')}if(t===1){const a=R(1,5),b=R(5,55);return NQ(`<b>${a} phút ${b} giây = ? giây</b>`,`${a} phút ${b} giây bằng bao nhiêu giây?`,a*60+b,`${a} × 60 + ${b} = ${a*60+b} (giây).`,'Giây')}if(t===2){const a=R(2,9);return NQ(`<b>${a} thế kỉ = ? năm</b>`,`${a} thế kỉ bằng bao nhiêu năm?`,a*100,`1 thế kỉ = 100 năm.`,'Thế kỉ')}const y=R(1001,2099),c=Math.ceil(y/100);return NQ(`Năm ${y} thuộc thế kỉ thứ mấy?`,`Năm ${y} thuộc thế kỉ thứ mấy?`,c,`Từ năm ${(c-1)*100+1} đến năm ${c*100} là thế kỉ ${c}.`,'Thế kỉ')},
 roman:()=>()=>{const R2=n=>{const T=[[10,'X'],[9,'IX'],[5,'V'],[4,'IV'],[1,'I']];let s='';for(const[v,r]of T)while(n>=v){s+=r;n-=v}return s};const n=R(11,21);return CQ(`Thế kỉ ${n} viết bằng số La Mã là:`,`Thế kỉ ${n} viết bằng số La Mã là gì?`,R2(n),[R2(n+1),R2(n-1),R2(n>=20?n-10:n+10)].filter(x=>x!==R2(n)),`${n} = ${R2(n)}.`,'Thế kỉ, số La Mã',1)},
 wood:()=>()=>{const a=R(6,15),b=R(3,a-1);return WQ(`Tấm gỗ hình chữ nhật dài ${a} dm, rộng ${b} dm. Tính diện tích tấm gỗ theo đề-xi-mét vuông.`,`Tấm gỗ dài ${a}, rộng ${b} đề-xi-mét. Diện tích bao nhiêu đề-xi-mét vuông?`,a*b,`${a} × ${b} = ${a*b} (dm²).`)},
 table:()=>()=>{const a=R(1,2),b=R(1,9),w=R(4,9);return WQ(`Mặt bàn hình chữ nhật dài ${a} m ${b} dm, rộng ${w} dm. Tính diện tích mặt bàn theo đề-xi-mét vuông.`,`Mặt bàn dài ${a} mét ${b} đề-xi-mét, rộng ${w} đề-xi-mét. Diện tích bao nhiêu đề-xi-mét vuông?`,(a*10+b)*w,`${a} m ${b} dm = ${a*10+b} dm; ${a*10+b} × ${w} = ${(a*10+b)*w} (dm²).`)},
};
const QA4={
 add:()=>()=>{const a=R(100000,899999),b=R(10000,99999),v=a+b;return CQ(`<b>${fN(a)} + ${fN(b)} = ?</b>`,`Tính tổng hai số này.`,fN(v),[fN(v+1000),fN(v-10),fN(v+10000)],`Cộng từ hàng đơn vị, nhớ sang hàng bên trái: ${fN(v)}.`,'Phép cộng số có nhiều chữ số',1)},
 sub:()=>()=>{const a=R(200000,999999),b=R(10000,a-50000),v=a-b;return CQ(`<b>${fN(a)} − ${fN(b)} = ?</b>`,`Tính hiệu hai số này.`,fN(v),[fN(v+1000),fN(v-10),fN(v+10000)],`Trừ từ hàng đơn vị, nhớ sang hàng bên trái: ${fN(v)}.`,'Phép trừ số có nhiều chữ số',1)},
 find:()=>()=>{const a=R(1000,9999),b=R(1000,9999);return Math.random()<.5?NQ(`Tìm ☐: <b>☐ − ${fN(b)} = ${fN(a)}</b>`,`Số nào trừ ${b} bằng ${a}?`,a+b,`☐ = ${fN(a)} + ${fN(b)} = ${fN(a+b)}.`,'Tìm thành phần chưa biết'):NQ(`Tìm ☐: <b>☐ + ${fN(b)} = ${fN(a+b)}</b>`,`Số nào cộng ${b} bằng ${a+b}?`,a,`☐ = ${fN(a+b)} − ${fN(b)} = ${fN(a)}.`,'Tìm thành phần chưa biết')},
 comm:()=>()=>{const a=R(100,9999),b=R(100,9999);return NQ(`Không tính, viết số thích hợp: <b>${fN(a)} + ${fN(b)} = ${fN(b)} + ☐</b>`,`${a} cộng ${b} bằng ${b} cộng mấy?`,a,`Đổi chỗ các số hạng thì tổng không đổi: ☐ = ${fN(a)}.`,'Tính chất giao hoán')},
 assoc:()=>()=>{const a=R(10,99),b=R(10,99),c=R(10,99);return NQ(`Viết số thích hợp: <b>(${a} + ${b}) + ${c} = ${a} + (${b} + ☐)</b>`,`${a} cộng ${b}, rồi cộng ${c}, bằng ${a} cộng, ${b} cộng mấy?`,c,`Tính chất kết hợp: ☐ = ${c}.`,'Tính chất kết hợp')},
 conv:()=>()=>{const r=pick([100,200,300,500,1000]),b=R(11,r-11),c=r-b,a=R(100,999);return NQ(`Tính bằng cách thuận tiện: <b>${a} + ${b} + ${c}</b>`,`Tính thuận tiện: ${a} cộng ${b} cộng ${c}.`,a+r,`${a} + (${b} + ${c}) = ${a} + ${r} = ${a+r}.`,'Tính bằng cách thuận tiện')},
 sumDiff:()=>()=>{const t=R(0,3);const s=(x,y)=>[x+y,x-y];if(t===0){const ba=R(60,70),ong=ba+R(2,8);const [S,D]=s(ong,ba);return NQ(`Tổng số tuổi của ông và bà là ${S} tuổi. Ông hơn bà ${D} tuổi. Hỏi ông bao nhiêu tuổi?`,`Tổng tuổi ông bà ${S}, ông hơn bà ${D} tuổi. Ông bao nhiêu tuổi?`,ong,`Tuổi ông: (${S} + ${D}) : 2 = ${ong} (tuổi).`,'Toán lời văn: tổng và hiệu')}if(t===1){const v=R(15,30),n=v+R(2,10);const [S,D]=s(n,v);return NQ(`Nam và Việt câu được tất cả ${S} con cá. Nam câu nhiều hơn Việt ${D} con. Hỏi Việt câu được bao nhiêu con cá?`,`Hai bạn câu ${S} con cá, Nam nhiều hơn Việt ${D} con. Việt câu được bao nhiêu?`,v,`Việt: (${S} − ${D}) : 2 = ${v} (con).`,'Toán lời văn: tổng và hiệu')}if(t===2){const th=R(15,30)*10,ca=th+R(2,15)*10;const [S,D]=s(ca,th);return NQ(`Hai ngọn núi được trồng tất cả ${S} cây tùng. Núi thấp trồng ít hơn núi cao ${D} cây. Hỏi núi cao trồng bao nhiêu cây tùng?`,`Hai núi trồng ${S} cây, núi thấp ít hơn ${D} cây. Núi cao trồng bao nhiêu?`,ca,`Núi cao: (${S} + ${D}) : 2 = ${ca} (cây).`,'Toán lời văn: tổng và hiệu')}const p=R(60,110),q=p+R(4,30);const [S,D]=s(q,p);return NQ(`Có ${S} cuốn sách xếp lên hai giá. Giá bên phải nhiều hơn giá bên trái ${D} cuốn. Hỏi giá bên trái có bao nhiêu cuốn sách?`,`${S} cuốn sách trên hai giá, giá phải nhiều hơn ${D} cuốn. Giá trái có bao nhiêu?`,p,`Giá trái: (${S} − ${D}) : 2 = ${p} (cuốn).`,'Toán lời văn: tổng và hiệu')},
 expr:()=>()=>{const a=R(1000,9000),b=R(100,999),c=R(100,999);return NQ(`Tính giá trị biểu thức: <b>${fN(a)} + ${b} − ${c}</b>`,`Tính ${a} cộng ${b} trừ ${c}.`,a+b-c,`${fN(a)} + ${b} = ${fN(a+b)}; ${fN(a+b)} − ${c} = ${fN(a+b-c)}.`,'Tính giá trị biểu thức')},
};
/* ---------- LỚP 5 ---------- */
const QDC5={
 add:()=>()=>{const a=R(101,999),b=R(11,999),d=pick([1,2]);const v=a+b;return CQ(`<b>${dz(a,d)} + ${dz(b,d)} = ?</b>`,`Tính tổng hai số thập phân.`,dz(v,d),[dz(v,d===1?2:1),dz(v+10**(d-1)*10,d),dz(a+b*10,d)].filter(x=>x!==dz(v,d)),`Đặt tính, các dấu phẩy thẳng cột: ${dz(v,d)}.`,'Phép cộng số thập phân',1)},
 sub:()=>()=>{const a=R(300,999),b=R(11,a-50),d=pick([1,2]);const v=a-b;return CQ(`<b>${dz(a,d)} − ${dz(b,d)} = ?</b>`,`Tính hiệu hai số thập phân.`,dz(v,d),[dz(v,d===1?2:1),dz(v+10,d),dz(a-b*10>0?a-b*10:v+100,d)].filter(x=>x!==dz(v,d)),`Đặt tính, các dấu phẩy thẳng cột: ${dz(v,d)}.`,'Phép trừ số thập phân',1)},
 tf:()=>()=>{const a=R(11,99),b=R(11,99),ok=Math.random()<.5,v=ok?a+b:a+b*10;return{type:'tf',q:`<b>${dz(a,1)} + ${dz(b,1)} = ${dz(v,1)}</b>`,say:'Phép tính này đúng hay sai?',a:ok,sol:`${dz(a,1)} + ${dz(b,1)} = ${dz(a+b,1)}.`,kind:'Cộng số thập phân'}},
 mulN:()=>()=>{const a=R(11,99),b=R(2,9),d=pick([1,2]);return CQ(`<b>${dz(a,d)} × ${b} = ?</b>`,`Tính ${dz(a,d)} nhân ${b}.`,dz(a*b,d),[dz(a*b,d===1?2:1),dz(a*b,0),dz(a*b+b,d)].filter(x=>x!==dz(a*b,d)),`Nhân như số tự nhiên rồi tách ${d} chữ số ở phần thập phân: ${dz(a*b,d)}.`,'Phép nhân số thập phân',1)},
 mulD:()=>()=>{const a=R(11,49),b=R(11,49);return CQ(`<b>${dz(a,1)} × ${dz(b,1)} = ?</b>`,`Tính ${dz(a,1)} nhân ${dz(b,1)}.`,dz(a*b,2),[dz(a*b,1),dz(a*b,3),dz(a*b+a,2)].filter(x=>x!==dz(a*b,2)),`${a} × ${b} = ${a*b}; hai thừa số có tổng 2 chữ số thập phân nên tích là ${dz(a*b,2)}.`,'Phép nhân số thập phân',1)},
 known:()=>()=>{const a=R(12,98),b=R(12,98),p=a*b;const k=pick([[1,0],[1,1],[0,1]]);return CQ(`Biết <b>${a} × ${b} = ${fN(p)}</b>. Không tính, cho biết <b>${dz(a,k[0])} × ${dz(b,k[1])}</b> = ?`,`Biết ${a} nhân ${b} bằng ${p}. ${dz(a,k[0])} nhân ${dz(b,k[1])} bằng bao nhiêu?`,dz(p,k[0]+k[1]),[dz(p,k[0]+k[1]+1),dz(p,Math.max(0,k[0]+k[1]-1)),dz(p*10,k[0]+k[1]+2)].filter(x=>x!==dz(p,k[0]+k[1])),`Đếm số chữ số thập phân ở hai thừa số: ${k[0]+k[1]}, nên tích là ${dz(p,k[0]+k[1])}.`,'Phép nhân số thập phân',1)},
 div:()=>()=>{const b=R(2,9),q=R(11,999),a=b*q,d=pick([1,2]);return CQ(`<b>${dz(a,d)} : ${b} = ?</b>`,`Tính ${dz(a,d)} chia ${b}.`,dz(q,d),[dz(q,d===1?2:1),dz(q*10,d),dz(q+1,d)].filter(x=>x!==dz(q,d)),`Chia như số tự nhiên, đến phần thập phân thì đánh dấu phẩy: ${dz(q,d)}.`,'Phép chia số thập phân',1)},
 divD:()=>()=>{const b=R(2,9),q=R(2,30);const B=b,Q=q;return CQ(`<b>${dz(B*Q,1)} : ${dz(B,1)} = ?</b>`,`Tính ${dz(B*Q,1)} chia ${dz(B,1)}.`,String(Q),[dz(Q,1),String(Q*10),String(Q+1)].filter(x=>x!==String(Q)),`Nhân cả hai số với 10: ${B*Q} : ${B} = ${Q}.`,'Chia cho số thập phân',1)},
 pow10:()=>()=>{const a=R(101,9999),d=pick([1,2]),k=pick([10,100,1000]),z=String(k).length-1,mul=Math.random()<.6;const good=mul?(d>=z?dz(a,d-z):fN(a*10**(z-d))):dz(a,d+z);return CQ(`<b>${dz(a,d)} ${mul?'×':':'} ${fN(k)} = ?</b>`,`Tính nhẩm ${dz(a,d)} ${mul?'nhân':'chia'} ${k}.`,good,[mul?dz(a,d+z):(d>=z?dz(a,d-z):fN(a*10**(z-d))),dz(a,d),mul?dz(a,Math.max(0,d-z+1)):dz(a,d+z-1)].filter(x=>x!==good),`${mul?'Nhân':'Chia'} với ${fN(k)}: dời dấu phẩy sang ${mul?'phải':'trái'} ${z} chữ số.`,'Nhân, chia với 10; 100; 1 000',1)},
 pt1:()=>()=>{const a=R(101,9999),d=pick([1,2]),k=pick([[0.1,1],[0.01,2]]);const good=dz(a,d+k[1]);return CQ(`<b>${dz(a,d)} × ${String(k[0]).replace('.',',')} = ?</b>`,`Tính nhẩm ${dz(a,d)} nhân ${String(k[0]).replace('.',',')}.`,good,[d>=k[1]?dz(a,d-k[1]):fN(a*10**(k[1]-d)),dz(a,d),dz(a,d+k[1]+1)].filter(x=>x!==good),`Nhân với ${String(k[0]).replace('.',',')}: dời dấu phẩy sang trái ${k[1]} chữ số.`,'Nhân với 0,1; 0,01',1)},
 cmp:()=>()=>{const a=R(11,99),b=R(2,9),c=a*b+pick([-3,0,0,4]);return SG(0,0,`${dz(a,1)} × ${b}`,dz(c,1),'So sánh kết quả',a*b,c)},
 word:()=>()=>{const r=R(300,450),n=R(20,60),v=R(20,60);return CQ(`Rô-bốt nặng ${dz(r,1)} kg. Nam nặng hơn Rô-bốt ${dz(n,1)} kg. Hỏi Nam nặng bao nhiêu ki-lô-gam?`,`Rô-bốt nặng ${dz(r,1)} ki-lô-gam, Nam nặng hơn ${dz(n,1)}. Nam nặng bao nhiêu?`,dz(r+n,1)+' kg',[dz(r-n,1)+' kg',dz(r+n*10,1)+' kg',dz(r+n+10,1)+' kg'],`${dz(r,1)} + ${dz(n,1)} = ${dz(r+n,1)} (kg).`,'Toán lời văn: số thập phân',0)},
};
function triSvg(t){const P=t==='vuong'?[[10,80],[110,80],[10,14]]:t==='nhon'?[[10,80],[120,80],[70,10]]:[[10,80],[80,80],[150,20]];return`<svg viewBox="0 0 160 90" width="160" height="90" aria-hidden="true"><polygon points="${P.map(p=>p.join(',')).join(' ')}" fill="#E6F4FD" stroke="#1F2A5A" stroke-width="4"/>${t==='vuong'?'<path d="M10 66H24V80" fill="none" stroke="#F04A1B" stroke-width="3"/>':''}</svg>`}
function trapSvg(k,sz=56){const P=k==='trap'?[[4,56],[60,56],[46,14],[16,14]]:k==='trapR'?[[6,56],[60,56],[34,12],[6,12]]:k==='quad'?[[6,56],[58,48],[46,8],[14,18]]:[[6,56],[58,56],[32,8]];return`<svg viewBox="0 0 64 64" width="${sz}" height="${sz}" aria-hidden="true"><polygon points="${P.map(p=>p.join(',')).join(' ')}" fill="#E6F4FD" stroke="#1F2A5A" stroke-width="4"/></svg>`}
const pi=n=>dz(Math.round(n*314)/1,2);
const QH5={
 triT:()=>()=>{const t=pick(['vuong','nhon','tu']),N={vuong:'Tam giác vuông',nhon:'Tam giác có ba góc nhọn',tu:'Tam giác có một góc tù'};const o=['vuong','nhon','tu'];return{type:'opt',cols:1,q:'Hình tam giác dưới đây là loại nào?',say:'Hình tam giác dưới đây là loại tam giác nào?',pic:`<div class="g1grp">${triSvg(t)}</div>`,opts:o.map(v=>({h:N[v],v})),a:o.indexOf(t),sol:`Đây là ${N[t].toLowerCase()}.`,kind:'Các loại hình tam giác'}},
 triA:()=>()=>{const a=R(3,20),h=R(2,16);if(a*h%2)return QH5.triA()();return NQ(`Hình tam giác có độ dài đáy ${a} cm, chiều cao ${h} cm. Diện tích hình tam giác là bao nhiêu xăng-ti-mét vuông?`,`Tam giác đáy ${a}, cao ${h} xăng-ti-mét. Diện tích bao nhiêu?`,a*h/2,`S = ${a} × ${h} : 2 = ${a*h/2} (cm²).`,'Diện tích hình tam giác')},
 triH:()=>()=>{const a=R(4,16),h=R(2,12);if(a*h%2)return QH5.triH()();return NQ(`Hình tam giác có diện tích ${a*h/2} cm², độ dài đáy ${a} cm. Chiều cao của tam giác là bao nhiêu xăng-ti-mét?`,`Tam giác có diện tích ${a*h/2}, đáy ${a}. Chiều cao bao nhiêu?`,h,`h = ${a*h/2} × 2 : ${a} = ${h} (cm).`,'Diện tích hình tam giác')},
 trapPick:()=>()=>{const ks=shuf(['trap','trapR','trap','quad','tri','quad']);return{type:'pick',q:'Chạm vào <b>tất cả</b> hình thang.',say:'Hình thang có một cặp cạnh đối diện song song. Chạm vào tất cả hình thang rồi bấm kiểm tra.',opts:ks.map(k=>trapSvg(k,52)),a:ks.map((k,i)=>k.startsWith('trap')?i:-1).filter(i=>i>=0),sol:'Hình thang có hai cạnh đáy song song với nhau.',kind:'Hình thang'}},
 trapA:()=>()=>{const a=R(5,20),b=R(2,a-1),h=R(2,12);if((a+b)*h%2)return QH5.trapA()();return NQ(`Hình thang có hai đáy dài ${a} cm và ${b} cm, chiều cao ${h} cm. Diện tích hình thang là bao nhiêu xăng-ti-mét vuông?`,`Hình thang đáy ${a} và ${b}, cao ${h} xăng-ti-mét. Diện tích bao nhiêu?`,(a+b)*h/2,`S = (${a} + ${b}) × ${h} : 2 = ${(a+b)*h/2} (cm²).`,'Diện tích hình thang')},
 trapF:()=>()=>{const c=pick([['Hình thang có hai cạnh đáy song song.',true],['Hình thang vuông có một cạnh bên vuông góc với hai đáy.',true],['Hình thang có bốn cạnh bằng nhau.',false],['Diện tích hình thang bằng tổng hai đáy nhân với chiều cao rồi chia cho 2.',true],['Hình thang có ba cạnh.',false]]);return{type:'tf',q:c[0],say:c[0]+' Đúng hay sai?',a:c[1],sol:c[1]?'Câu này đúng.':'Câu này sai.',kind:'Hình thang'}},
 circC:()=>()=>{const d=R(2,20),byR=Math.random()<.5;return byR&&d%2===0?CQ(`Hình tròn có bán kính ${d/2} cm. Chu vi hình tròn là:`,`Hình tròn bán kính ${d/2} xăng-ti-mét. Chu vi là bao nhiêu?`,pi(d)+' cm',[pi(d/2)+' cm',pi(d*d/4)+' cm',pi(d*2)+' cm'],`C = ${d/2} × 2 × 3,14 = ${pi(d)} (cm).`,'Chu vi hình tròn'):CQ(`Hình tròn có đường kính ${d} cm. Chu vi hình tròn là:`,`Hình tròn đường kính ${d} xăng-ti-mét. Chu vi là bao nhiêu?`,pi(d)+' cm',[pi(d*2)+' cm',pi(d/2)+' cm',dz(d*314+314,2)+' cm'],`C = ${d} × 3,14 = ${pi(d)} (cm).`,'Chu vi hình tròn')},
 circA:()=>()=>{const r=R(1,15);return CQ(`Hình tròn có bán kính ${r} dm. Diện tích hình tròn là:`,`Hình tròn bán kính ${r} đề-xi-mét. Diện tích là bao nhiêu?`,pi(r*r)+' dm²',[pi(r*2)+' dm²',pi(r*r*4)+' dm²',pi(r)+' dm²'].filter(x=>x!==pi(r*r)+' dm²'),`S = ${r} × ${r} × 3,14 = ${pi(r*r)} (dm²).`,'Diện tích hình tròn')},
 circF:()=>()=>{const c=pick([['Chu vi hình tròn bằng đường kính nhân với 3,14.',true],['Diện tích hình tròn bằng bán kính nhân bán kính nhân 3,14.',true],['Chu vi hình tròn bằng bán kính nhân với 3,14.',false],['Đường kính dài gấp 2 lần bán kính.',true],['Hình tròn bán kính 2 cm có chu vi lớn hơn hình tròn đường kính 5 cm.',false]]);return{type:'tf',q:c[0],say:c[0]+' Đúng hay sai?',a:c[1],sol:c[1]?'Câu này đúng.':'Câu này sai.',kind:'Chu vi, diện tích hình tròn'}},
 well:()=>()=>{const r=R(3,9);return CQ(`Miệng giếng hình tròn có bán kính ${r} dm. Chu vi miệng giếng là:`,`Miệng giếng hình tròn bán kính ${r} đề-xi-mét. Chu vi là bao nhiêu?`,pi(r*2)+' dm',[pi(r)+' dm',pi(r*r)+' dm',pi(r*4)+' dm'],`C = ${r} × 2 × 3,14 = ${pi(r*2)} (dm).`,'Toán lời văn: hình tròn')},
 grid:()=>()=>{const a=R(3,8),b=R(1,a-1),h=R(2,6);if((a+b)*h%2)return QH5.grid()();return NQ(`Mỗi ô vuông có diện tích 1 cm². Hình thang có hai đáy dài ${a} ô và ${b} ô, chiều cao ${h} ô. Diện tích hình thang là bao nhiêu xăng-ti-mét vuông?`,`Hình thang trên lưới ô vuông, đáy ${a} và ${b} ô, cao ${h} ô. Diện tích bao nhiêu?`,(a+b)*h/2,`S = (${a} + ${b}) × ${h} : 2 = ${(a+b)*h/2} (cm²).`,'Diện tích hình thang')},
};
